configfiles.configfile:
import sys

seen = {}
for path in sys.argv[1:]:
    with open(path) as handle:
        for line in handle:
            if not line.startswith("\#"):
                break
            if line.startswith("\#\# COLDATA:"):
                for sample in line.split(":", 1)[1].strip().split(","):
                    if sample in seen:
                        sys.exit(
                            "Sample '%s' is in more than one input file. mirtop stats would keep only "
                            "one set of numbers for it; rename the samples or summarise the files separately." % sample
                        )
                    seen[sample] = path
